// Staff is the resolver for the staff field.
func (r *clientNoteResolver) Staff(ctx context.Context, obj *handlers.ClientNote) (*handlers.User, error) {
	loaders := r.GetLoaders(ctx)
	if loaders != nil {
		result := loaders.UserLoader.Load(ctx, obj.StaffID)
		user, err := result()
		if err != nil {
			return nil, err
		}
		if user == nil {
			return nil, nil
		}
		// Convert dataloader.User to handlers.User
		return &handlers.User{
			ID:          user.ID.String(),
			TenantID:    ptrString(user.TenantID.String()),
			Email:       user.Email,
			Name:        user.Name,
			Role:        user.Role,
			AvatarURL:   user.AvatarURL,
			Status:      boolToStatus(user.IsActive),
			LastLoginAt: user.LastLoginAt,
			CreatedAt:   user.CreatedAt,
			UpdatedAt:   user.UpdatedAt,
		}, nil
	}

	// Fallback to direct query
	var u handlers.User
	var id, tenantID uuid.UUID
	err := r.QueryRow(ctx, []interface{}{
		&id, &tenantID, &u.Name, &u.Email, &u.Role, &u.Status,
		&u.AvatarURL, &u.LastLoginAt, &u.CreatedAt, &u.UpdatedAt,
	}, `
		SELECT id, tenant_id, name, email, role, status,
		       avatar_url, last_login_at, created_at, updated_at
		FROM users
		WHERE id = $1 AND deleted_at IS NULL
	`, obj.StaffID)
	if err != nil {
		return nil, nil
	}
	u.ID = id.String()
	tid := tenantID.String()
	u.TenantID = &tid
	return &u, nil
}

func ptrString(s string) *string {
	return &s
}

func boolToStatus(active bool) string {
	if active {
		return "active"
	}
	return "inactive"
}

