// UnreadNotifications is the resolver for the unread_notifications field.
func (r *dashboardStatsResolver) UnreadNotifications(ctx context.Context, obj *handlers.DashboardStats) (int, error) {
	userID := ctx.Value(middleware.AuthUserID)
	if userID == nil {
		return 0, nil
	}

	var count int
	err := r.WithTransaction(ctx, func(tx pgx.Tx) error {
		return tx.QueryRow(ctx, `
			SELECT COUNT(*) FROM notifications
			WHERE user_id = $1 AND is_read = false AND dismissed_at IS NULL
		`, userID).Scan(&count)
	})
	if err != nil {
		return 0, nil
	}
	return count, nil
}

