func (r *documentResolver) loadUser(ctx context.Context, userID uuid.UUID) (*handlers.User, error) {
	loaders := r.GetLoaders(ctx)
	if loaders != nil {
		result := loaders.UserLoader.Load(ctx, userID)
		user, err := result()
		if err != nil || user == nil {
			return nil, nil
		}
		return &handlers.User{
			ID:          user.ID.String(),
			TenantID:    ptrString(user.TenantID.String()),
			Email:       user.Email,
			Name:        user.Name,
			Role:        user.Role,
			AvatarURL:   user.AvatarURL,
			Status:      boolToStatus(user.IsActive),
			LastLoginAt: user.LastLoginAt,
			CreatedAt:   user.CreatedAt,
			UpdatedAt:   user.UpdatedAt,
		}, nil
	}
	return nil, nil
}

