// Client is the resolver for the client field.
func (r *emailResolver) Client(ctx context.Context, obj *handlers.Email) (*handlers.Client, error) {
	if obj.ClientID == nil {
		return nil, nil
	}
	loaders := r.GetLoaders(ctx)
	if loaders != nil {
		result := loaders.ClientLoader.Load(ctx, *obj.ClientID)
		client, err := result()
		if err != nil || client == nil {
			return nil, nil
		}
		return &handlers.Client{
			ID:          client.ID,
			TenantID:    client.TenantID,
			CompanyName: client.CompanyName,
			ContactName: client.ContactName,
			Email:       client.Email,
			Status:      client.Status,
			EmailStatus: client.EmailStatus,
			CreatedAt:   client.CreatedAt,
			UpdatedAt:   client.UpdatedAt,
		}, nil
	}
	return nil, nil
}

// Staff is the resolver for the staff field.
func (r *emailResolver) Staff(ctx context.Context, obj *handlers.Email) (*handlers.User, error) {
	if obj.StaffID == nil {
		return nil, nil
	}
	loaders := r.GetLoaders(ctx)
	if loaders != nil {
		result := loaders.UserLoader.Load(ctx, *obj.StaffID)
		user, err := result()
		if err != nil || user == nil {
			return nil, nil
		}
		return &handlers.User{
			ID:        user.ID.String(),
			TenantID:  ptrString(user.TenantID.String()),
			Email:     user.Email,
			Name:      user.Name,
			Role:      user.Role,
			AvatarURL: user.AvatarURL,
			Status:    boolToStatus(user.IsActive),
		}, nil
	}
	return nil, nil
}

