// MarkNotificationRead is the resolver for the mark_notification_read field.
func (r *mutationResolver) MarkNotificationRead(ctx context.Context, id uuid.UUID) (*handlers.Notification, error) {
	userIDVal := ctx.Value(middleware.AuthUserID)
	if userIDVal == nil {
		return nil, fmt.Errorf("unauthorized")
	}
	userID, ok := userIDVal.(uuid.UUID)
	if !ok {
		return nil, fmt.Errorf("invalid user ID")
	}

	var n handlers.Notification
	var dismissedAt *time.Time
	err := r.WithTransaction(ctx, func(tx pgx.Tx) error {
		return tx.QueryRow(ctx, `
			UPDATE notifications
			SET is_read = true
			WHERE id = $1 AND user_id = $2 AND dismissed_at IS NULL
			RETURNING id, tenant_id, user_id, type, title, message,
			          entity_type, entity_id, is_read, dismissed_at, created_at
		`, id, userID).Scan(
			&n.ID, &n.TenantID, &n.UserID, &n.Type, &n.Title, &n.Message,
			&n.EntityType, &n.EntityID, &n.IsRead, &dismissedAt, &n.CreatedAt,
		)
	})
	_ = dismissedAt // Silence unused warning
	if err != nil {
		return nil, fmt.Errorf("notification not found")
	}
	return &n, nil
}

// MarkAllNotificationsRead is the resolver for the mark_all_notifications_read field.
func (r *mutationResolver) MarkAllNotificationsRead(ctx context.Context) (int, error) {
	userIDVal := ctx.Value(middleware.AuthUserID)
	if userIDVal == nil {
		return 0, fmt.Errorf("unauthorized")
	}
	userID, ok := userIDVal.(uuid.UUID)
	if !ok {
		return 0, fmt.Errorf("invalid user ID")
	}

	var count int64
	err := r.WithTransaction(ctx, func(tx pgx.Tx) error {
		tag, err := tx.Exec(ctx, `
			UPDATE notifications
			SET is_read = true
			WHERE user_id = $1 AND is_read = false AND dismissed_at IS NULL
		`, userID)
		if err != nil {
			return err
		}
		count = tag.RowsAffected()
		return nil
	})
	if err != nil {
		return 0, err
	}
	return int(count), nil
}

// DismissNotification is the resolver for the dismiss_notification field.
func (r *mutationResolver) DismissNotification(ctx context.Context, id uuid.UUID) (bool, error) {
	userIDVal := ctx.Value(middleware.AuthUserID)
	if userIDVal == nil {
		return false, fmt.Errorf("unauthorized")
	}
	userID, ok := userIDVal.(uuid.UUID)
	if !ok {
		return false, fmt.Errorf("invalid user ID")
	}

	err := r.WithTransaction(ctx, func(tx pgx.Tx) error {
		now := time.Now()
		_, err := tx.Exec(ctx, `
			UPDATE notifications
			SET dismissed_at = $1
			WHERE id = $2 AND user_id = $3 AND dismissed_at IS NULL
		`, now, id, userID)
		return err
	})
	return err == nil, err
}

