// Dashboard is the resolver for the dashboard field.
func (r *queryResolver) Dashboard(ctx context.Context) (*model.Dashboard, error) {
	// Build dashboard stats
	var stats handlers.DashboardStats

	err := r.WithTransaction(ctx, func(tx pgx.Tx) error {
		// Client stats
		err := tx.QueryRow(ctx, `
			SELECT
				COUNT(*) as total,
				COUNT(*) FILTER (WHERE status = 'active') as active
			FROM clients
			WHERE deleted_at IS NULL
		`).Scan(&stats.TotalClients, &stats.ActiveClients)
		if err != nil {
			return err
		}

		// Service stats
		err = tx.QueryRow(ctx, `
			SELECT
				COUNT(*) as total,
				COUNT(*) FILTER (WHERE status = 'in_progress') as in_progress,
				COUNT(*) FILTER (WHERE status NOT IN ('completed', 'cancelled') AND deadline < CURRENT_DATE) as overdue
			FROM services
			WHERE 1=1
		`).Scan(&stats.TotalServices, &stats.ServicesInProgress, &stats.ServicesOverdue)
		if err != nil {
			return err
		}

		// Document stats
		err = tx.QueryRow(ctx, `
			SELECT
				COUNT(*) as total,
				COUNT(*) FILTER (WHERE status IN ('uploaded', 'pending_review', 'under_review')) as pending
			FROM documents
			WHERE deleted_at IS NULL
		`).Scan(&stats.TotalDocuments, &stats.DocumentsPending)
		if err != nil {
			return err
		}

		return nil
	})
	if err != nil {
		log.Error().Err(err).Msg("Failed to fetch dashboard stats")
	}

	// Build urgent items
	var urgentItems []*model.UrgentItem
	_ = r.WithTransaction(ctx, func(tx pgx.Tx) error {
		rows, err := tx.Query(ctx, `
			SELECT s.id, s.name, c.company_name, s.deadline, s.priority
			FROM services s
			JOIN clients c ON s.client_id = c.id
			WHERE s.status NOT IN ('completed', 'cancelled')
			  AND s.deadline < CURRENT_DATE + INTERVAL '3 days'
			ORDER BY s.deadline ASC
			LIMIT 5
		`)
		if err != nil {
			return err
		}
		defer rows.Close()

		for rows.Next() {
			var item model.UrgentItem
			var deadline *time.Time
			if err := rows.Scan(&item.EntityID, &item.Title, &item.ClientName, &deadline, &item.Priority); err != nil {
				continue
			}
			item.Type = "service"
			item.Description = "Service deadline approaching"
			item.DueAt = deadline
			urgentItems = append(urgentItems, &item)
		}
		return nil
	})

	// Build deadlines
	var deadlines []*model.DeadlineItem
	_ = r.WithTransaction(ctx, func(tx pgx.Tx) error {
		rows, err := tx.Query(ctx, `
			SELECT s.id, s.name, s.client_id, c.company_name, s.deadline, s.status, s.priority,
			       s.docs_received, s.docs_required
			FROM services s
			JOIN clients c ON s.client_id = c.id
			WHERE s.status NOT IN ('completed', 'cancelled')
			  AND s.deadline IS NOT NULL
			  AND s.deadline <= CURRENT_DATE + INTERVAL '14 days'
			ORDER BY s.deadline ASC
			LIMIT 10
		`)
		if err != nil {
			return err
		}
		defer rows.Close()

		for rows.Next() {
			var item model.DeadlineItem
			var status, priority string
			var docsReceived, docsRequired int
			if err := rows.Scan(
				&item.ServiceID, &item.ServiceName, &item.ClientID, &item.ClientName,
				&item.Deadline, &status, &priority, &docsReceived, &docsRequired,
			); err != nil {
				continue
			}
			item.Status = statusToServiceStatus(status)
			item.Priority = statusToServicePriority(priority)
			item.DaysRemaining = int(time.Until(item.Deadline).Hours() / 24)
			if docsRequired > 0 {
				item.DocsProgress = fmt.Sprintf("%d/%d", docsReceived, docsRequired)
			} else {
				item.DocsProgress = "N/A"
			}
			deadlines = append(deadlines, &item)
		}
		return nil
	})

	// Build recent activity
	var activities []*handlers.ActivityItem
	_ = r.WithTransaction(ctx, func(tx pgx.Tx) error {
		rows, err := tx.Query(ctx, `
			SELECT id, action, entity_type, entity_id, metadata->>'description', metadata->>'user_name', created_at
			FROM audit_logs
			ORDER BY created_at DESC
			LIMIT 10
		`)
		if err != nil {
			return err
		}
		defer rows.Close()

		for rows.Next() {
			var item handlers.ActivityItem
			if err := rows.Scan(
				&item.ID, &item.Action, &item.EntityType, &item.EntityID,
				&item.Description, &item.UserName, &item.CreatedAt,
			); err != nil {
				continue
			}
			activities = append(activities, &item)
		}
		return nil
	})

	// Build kanban board
	kanban := &model.KanbanBoard{
		NotStarted:   []*model.KanbanService{},
		InProgress:   []*model.KanbanService{},
		AwaitingInfo: []*model.KanbanService{},
		UnderReview:  []*model.KanbanService{},
		Completed:    []*model.KanbanService{},
	}
	_ = r.WithTransaction(ctx, func(tx pgx.Tx) error {
		rows, err := tx.Query(ctx, `
			SELECT s.id, s.name, s.client_id, c.company_name, s.priority, s.deadline,
			       s.docs_received, s.docs_required, s.status
			FROM services s
			JOIN clients c ON s.client_id = c.id
			WHERE s.status NOT IN ('cancelled')
			ORDER BY s.deadline ASC NULLS LAST
			LIMIT 50
		`)
		if err != nil {
			return err
		}
		defer rows.Close()

		for rows.Next() {
			var item model.KanbanService
			var priority, status string
			var docsReceived, docsRequired int
			if err := rows.Scan(
				&item.ID, &item.Name, &item.ClientID, &item.ClientName,
				&priority, &item.Deadline, &docsReceived, &docsRequired, &status,
			); err != nil {
				continue
			}
			item.Priority = statusToServicePriority(priority)
			if docsRequired > 0 {
				item.DocsProgress = fmt.Sprintf("%d/%d", docsReceived, docsRequired)
			} else {
				item.DocsProgress = "N/A"
			}

			switch strings.ToLower(status) {
			case "not_started":
				kanban.NotStarted = append(kanban.NotStarted, &item)
			case "in_progress":
				kanban.InProgress = append(kanban.InProgress, &item)
			case "awaiting_info":
				kanban.AwaitingInfo = append(kanban.AwaitingInfo, &item)
			case "under_review":
				kanban.UnderReview = append(kanban.UnderReview, &item)
			case "completed":
				kanban.Completed = append(kanban.Completed, &item)
			}
		}
		return nil
	})

	return &model.Dashboard{
		Stats:          &stats,
		UrgentItems:    urgentItems,
		Deadlines:      deadlines,
		RecentActivity: activities,
		Kanban:         kanban,
	}, nil
}

