// Clients is the resolver for the clients field.
func (r *queryResolver) Clients(ctx context.Context, filter *model.ClientFilter, first *int, after *string) (*model.ClientConnection, error) {
	limit := 20
	if first != nil {
		limit = *first
	}

	var afterID uuid.UUID
	if after != nil {
		var err error
		afterID, err = decodeCursor(*after)
		if err != nil {
			return nil, fmt.Errorf("invalid cursor")
		}
	}

	var clients []*handlers.Client
	var totalCount int

	err := r.WithTransaction(ctx, func(tx pgx.Tx) error {
		// Build query with filters
		query := `
			SELECT id, tenant_id, user_id, company_name, contact_name, email,
			       phone, address, year_end, utr, company_number, company_type,
			       incorporation_date, vat_number, vat_quarter, status, risk_score,
			       email_status, last_contact_at, created_at, updated_at
			FROM clients
			WHERE deleted_at IS NULL
		`
		countQuery := `SELECT COUNT(*) FROM clients WHERE deleted_at IS NULL`
		args := []interface{}{}
		argIdx := 1

		if filter != nil {
			if filter.Status != nil {
				query += fmt.Sprintf(" AND status = $%d", argIdx)
				countQuery += fmt.Sprintf(" AND status = $%d", argIdx)
				args = append(args, strings.ToLower(string(*filter.Status)))
				argIdx++
			}
			if filter.Search != nil && *filter.Search != "" {
				query += fmt.Sprintf(" AND (company_name ILIKE $%d OR contact_name ILIKE $%d OR email ILIKE $%d)", argIdx, argIdx, argIdx)
				countQuery += fmt.Sprintf(" AND (company_name ILIKE $%d OR contact_name ILIKE $%d OR email ILIKE $%d)", argIdx, argIdx, argIdx)
				args = append(args, "%"+*filter.Search+"%")
				argIdx++
			}
			if filter.AssignedTo != nil {
				query += fmt.Sprintf(" AND id IN (SELECT client_id FROM staff_clients WHERE staff_id = $%d)", argIdx)
				countQuery += fmt.Sprintf(" AND id IN (SELECT client_id FROM staff_clients WHERE staff_id = $%d)", argIdx)
				args = append(args, *filter.AssignedTo)
				argIdx++
			}
		}

		if afterID != uuid.Nil {
			query += fmt.Sprintf(" AND id > $%d", argIdx)
			args = append(args, afterID)
			argIdx++
		}

		query += " ORDER BY company_name ASC"
		query += fmt.Sprintf(" LIMIT $%d", argIdx)
		args = append(args, limit+1) // Fetch one extra to check if there's a next page

		// Get total count
		countArgs := args[:len(args)-1]
		if afterID != uuid.Nil {
			countArgs = countArgs[:len(countArgs)-1]
		}
		if err := tx.QueryRow(ctx, countQuery, countArgs...).Scan(&totalCount); err != nil {
			return err
		}

		// Get clients
		rows, err := tx.Query(ctx, query, args...)
		if err != nil {
			return err
		}
		defer rows.Close()

		for rows.Next() {
			var c handlers.Client
			if err := rows.Scan(
				&c.ID, &c.TenantID, &c.UserID, &c.CompanyName, &c.ContactName, &c.Email,
				&c.Phone, &c.Address, &c.YearEnd, &c.UTR, &c.CompanyNumber, &c.CompanyType,
				&c.IncorporationDate, &c.VATNumber, &c.VATQuarter, &c.Status, &c.RiskScore,
				&c.EmailStatus, &c.LastContactAt, &c.CreatedAt, &c.UpdatedAt,
			); err != nil {
				return err
			}
			clients = append(clients, &c)
		}
		return rows.Err()
	})
	if err != nil {
		return nil, err
	}

	hasNextPage := len(clients) > limit
	if hasNextPage {
		clients = clients[:limit]
	}

	edges := make([]*model.ClientEdge, len(clients))
	for i, c := range clients {
		edges[i] = &model.ClientEdge{
			Cursor: encodeCursor(c.ID),
			Node:   c,
		}
	}

	var startCursor, endCursor *string
	if len(edges) > 0 {
		startCursor = &edges[0].Cursor
		endCursor = &edges[len(edges)-1].Cursor
	}

	return &model.ClientConnection{
		Edges: edges,
		PageInfo: &model.PageInfo{
			HasNextPage:     hasNextPage,
			HasPreviousPage: after != nil,
			StartCursor:     startCursor,
			EndCursor:       endCursor,
		},
		TotalCount: totalCount,
	}, nil
}

