// TroublemakerClients is the resolver for the troublemaker_clients field.
func (r *queryResolver) TroublemakerClients(ctx context.Context, limit *int) ([]*model.TroublemakerClient, error) {
	l := 10
	if limit != nil {
		l = *limit
	}

	var clients []*model.TroublemakerClient
	err := r.WithTransaction(ctx, func(tx pgx.Tx) error {
		rows, err := tx.Query(ctx, `
			SELECT c.id, c.contact_name, c.company_name, c.risk_score, c.last_contact_at,
			       (SELECT COUNT(*) FROM services s WHERE s.client_id = c.id AND s.status NOT IN ('completed', 'cancelled') AND s.deadline < CURRENT_DATE) as overdue_services,
			       (SELECT COUNT(*) FROM documents d WHERE d.client_id = c.id AND d.status = 'requested') as pending_documents
			FROM clients c
			WHERE c.risk_score IS NOT NULL AND c.risk_score >= 70 AND c.deleted_at IS NULL
			ORDER BY c.risk_score DESC
			LIMIT $1
		`, l)
		if err != nil {
			return err
		}
		defer rows.Close()

		for rows.Next() {
			var c model.TroublemakerClient
			var riskScore *int
			if err := rows.Scan(
				&c.ClientID, &c.ClientName, &c.CompanyName, &riskScore, &c.LastContactAt,
				&c.OverdueServices, &c.PendingDocuments,
			); err != nil {
				continue
			}
			if riskScore != nil {
				c.RiskScore = *riskScore
				if *riskScore >= 90 {
					c.RiskLevel = "critical"
				} else if *riskScore >= 80 {
					c.RiskLevel = "high"
				} else {
					c.RiskLevel = "medium"
				}
			}
			c.RiskFactors = []*model.RiskFactor{}
			c.RecommendedActions = []string{}
			clients = append(clients, &c)
		}
		return rows.Err()
	})
	if err != nil {
		return []*model.TroublemakerClient{}, nil
	}
	return clients, nil
}

