// Search is the resolver for the search field.
func (r *queryResolver) Search(ctx context.Context, query string, limit *int) (*model.SearchResults, error) {
	l := 20
	if limit != nil {
		l = *limit
	}
	perType := l / 4

	searchPattern := "%" + query + "%"
	results := &model.SearchResults{
		Clients:    []*model.SearchResult{},
		Documents:  []*model.SearchResult{},
		Services:   []*model.SearchResult{},
		Emails:     []*model.SearchResult{},
		TotalCount: 0,
	}

	_ = r.WithTransaction(ctx, func(tx pgx.Tx) error {
		// Search clients
		rows, err := tx.Query(ctx, `
			SELECT id, company_name, contact_name, email
			FROM clients
			WHERE deleted_at IS NULL AND (
				company_name ILIKE $1 OR contact_name ILIKE $1 OR email ILIKE $1
			)
			LIMIT $2
		`, searchPattern, perType)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var r model.SearchResult
				var companyName, contactName, email string
				if err := rows.Scan(&r.ID, &companyName, &contactName, &email); err == nil {
					r.Type = "client"
					r.Title = companyName
					r.Subtitle = &contactName
					r.URL = "/dashboard/clients/" + r.ID.String()
					results.Clients = append(results.Clients, &r)
					results.TotalCount++
				}
			}
		}

		// Search documents
		rows2, err := tx.Query(ctx, `
			SELECT d.id, d.name, d.original_name, c.company_name
			FROM documents d
			LEFT JOIN clients c ON d.client_id = c.id
			WHERE d.deleted_at IS NULL AND (
				d.name ILIKE $1 OR d.original_name ILIKE $1
			)
			LIMIT $2
		`, searchPattern, perType)
		if err == nil {
			defer rows2.Close()
			for rows2.Next() {
				var r model.SearchResult
				var name, origName string
				var clientName *string
				if err := rows2.Scan(&r.ID, &name, &origName, &clientName); err == nil {
					r.Type = "document"
					r.Title = name
					r.Subtitle = clientName
					r.URL = "/dashboard/documents/" + r.ID.String()
					results.Documents = append(results.Documents, &r)
					results.TotalCount++
				}
			}
		}

		// Search services
		rows3, err := tx.Query(ctx, `
			SELECT s.id, s.name, c.company_name
			FROM services s
			LEFT JOIN clients c ON s.client_id = c.id
			WHERE s.name ILIKE $1
			LIMIT $2
		`, searchPattern, perType)
		if err == nil {
			defer rows3.Close()
			for rows3.Next() {
				var r model.SearchResult
				var name string
				var clientName *string
				if err := rows3.Scan(&r.ID, &name, &clientName); err == nil {
					r.Type = "service"
					r.Title = name
					r.Subtitle = clientName
					r.URL = "/dashboard/services/" + r.ID.String()
					results.Services = append(results.Services, &r)
					results.TotalCount++
				}
			}
		}

		// Search emails
		rows4, err := tx.Query(ctx, `
			SELECT id, subject, from_email
			FROM emails
			WHERE subject ILIKE $1 OR from_email ILIKE $1 OR to_email ILIKE $1
			LIMIT $2
		`, searchPattern, perType)
		if err == nil {
			defer rows4.Close()
			for rows4.Next() {
				var r model.SearchResult
				var subject, fromEmail string
				if err := rows4.Scan(&r.ID, &subject, &fromEmail); err == nil {
					r.Type = "email"
					r.Title = subject
					r.Subtitle = &fromEmail
					r.URL = "/dashboard/emails/" + r.ID.String()
					results.Emails = append(results.Emails, &r)
					results.TotalCount++
				}
			}
		}

		return nil
	})

	return results, nil
}

