func (r *queryResolver) DocumentTypes(ctx context.Context) ([]*handlers.DocumentType, error) {
	var types []*handlers.DocumentType
	err := r.WithTransaction(ctx, func(tx pgx.Tx) error {
		rows, err := tx.Query(ctx, `
			SELECT id, tenant_id, name, description, category, is_active, created_at
			FROM document_types
			WHERE is_active = true
			ORDER BY name ASC
		`)
		if err != nil {
			return err
		}
		defer rows.Close()

		for rows.Next() {
			var t handlers.DocumentType
			if err := rows.Scan(
				&t.ID, &t.TenantID, &t.Name, &t.Description, &t.Category,
				&t.IsActive, &t.CreatedAt,
			); err != nil {
				return err
			}
			types = append(types, &t)
		}
		return rows.Err()
	})
	if err != nil {
		return []*handlers.DocumentType{}, nil
	}
	return types, nil
}

