// Me is the resolver for the me field.
func (r *queryResolver) Me(ctx context.Context) (*handlers.User, error) {
	userIDVal := ctx.Value(middleware.AuthUserID)
	if userIDVal == nil {
		return nil, fmt.Errorf("unauthorized: no user in context")
	}
	userID, ok := userIDVal.(uuid.UUID)
	if !ok || userID == uuid.Nil {
		return nil, fmt.Errorf("unauthorized: invalid user ID")
	}

	var id uuid.UUID
	var tenantID *uuid.UUID
	var user handlers.User
	var lastLoginAt *time.Time
	var createdAt, updatedAt time.Time

	err := r.WithTransaction(ctx, func(tx pgx.Tx) error {
		return tx.QueryRow(ctx, `
			SELECT id, tenant_id, name, email, role, status, avatar_url, phone,
			       specialism, notes, last_login_at, created_at, updated_at
			FROM users
			WHERE id = $1 AND deleted_at IS NULL
		`, userID).Scan(
			&id, &tenantID, &user.Name, &user.Email, &user.Role, &user.Status,
			&user.AvatarURL, &user.Phone, &user.Specialism, &user.Notes,
			&lastLoginAt, &createdAt, &updatedAt,
		)
	})
	if err != nil {
		return nil, fmt.Errorf("failed to fetch user: %w", err)
	}

	user.ID = id.String()
	if tenantID != nil {
		tid := tenantID.String()
		user.TenantID = &tid
	}
	user.LastLoginAt = lastLoginAt
	user.CreatedAt = createdAt
	user.UpdatedAt = updatedAt

	return &user, nil
}

